"""Modulators: each wave's shape, the beat's push eased in and let go, a step pattern a step a period, and the
slider moved round its place - a place that follows whatever else sets the slider, the slider left there when the
modulator goes - on the held clock."""
# AI: below section was generated by an AI
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

from native import clock, modulate as mo

fails = []


def check(ok, what):
    print(("ok   " if ok else "FAIL ") + what)
    if not ok:
        fails.append(what)


near = lambda a, b, tol=1e-6: abs(a - b) <= tol                          # noqa: E731

# the waves, 0..1
check(near(mo.wave("sine", 0.0), 0.0) and near(mo.wave("sine", 0.5), 1.0), "sine from its low point")
check(near(mo.wave("triangle", 0.25), 0.5) and near(mo.wave("triangle", 0.5), 1.0), "triangle")
check(near(mo.wave("saw up", 0.3), 0.3) and near(mo.wave("saw down", 0.3), 0.7), "saws")
check(mo.wave("square", 0.2) == 1.0 and mo.wave("square", 0.7) == 0.0, "square")
r = [mo.wave("random", 0.9, c) for c in range(6)]
check(all(0.0 <= v <= 1.0 for v in r) and len(set(round(v, 4) for v in r)) > 3, "random: a level a period")
check(near(mo.wave("random", 0.0, 3), mo.wave("random", 0.999, 2), 1e-3), "random eased on from the last level")

# offsets
lfo = {"kind": "lfo", "shape": "sine", "period": 4, "depth": 100}
check(near(mo.offset(lfo, 0.0, None), -50.0) and near(mo.offset(lfo, 2.0, None), 50.0), "a wave swings depth in all")
beat = {"kind": "beat", "depth": 80, "decay": 0.4}
check(mo.offset(beat, 0, None) == 0.0, "no beat yet: no push")
check(near(mo.offset(beat, 0, 0.0), 0.0) and near(mo.offset(beat, 0, mo.ATTACK_S), 80.0), "the beat's push eased in")
check(mo.offset(beat, 0, mo.ATTACK_S + 0.2) < 40.0 and mo.offset(beat, 0, 3.0) < 1.0, "and let go")
steps = {"kind": "steps", "period": 1, "depth": 100, "steps": [1.0, 0.0, 0.5]}
check(near(mo.offset(steps, 0.5, None, 0.5), 50.0), "step 1 at full")
check(near(mo.offset(steps, 1.5, None, 0.5), -50.0), "step 2 at nothing")
check(near(mo.offset(steps, 3.5, None, 0.5), 50.0), "the pattern round again")
mid = mo.offset(steps, 1.0 + 0.025 / 0.5, None, 0.5)                    # 25 ms into step 2: half way down
check(-5.0 < mid < 5.0, f"eased from one step to the next ({mid})")


# applied: a stand-in app
class Eng:
    def __init__(self):
        self.fx = {"sx": 128, "ix": 100, "c1": 0, "c2": 0, "c3": 16}
        self.pushes = 0

    def push(self):
        self.pushes += 1


class Proj:
    def __init__(self):
        self.options = {"sequence": {"steps": [], "bpm": 60}}

    def save(self):
        pass


class App:
    def __init__(self):
        self.eng, self.project = Eng(), Proj()


app = App()
clock.hold()
try:
    mo.modulators(app).append({"key": "sx", "kind": "lfo", "shape": "square", "period": 2, "depth": 60, "on": True})
    mo.apply(app)                                                       # at 0 beats: the square's high half
    check(app.eng.fx["sx"] == 158 and mo.place(app, "sx") == 128, f"moved round its place ({app.eng.fx['sx']})")
    clock.step(1.5)                                                     # 1.5 beats at 60 bpm: the low half
    mo.apply(app)
    check(app.eng.fx["sx"] == 98, f"the low half ({app.eng.fx['sx']})")
    app.eng.fx["sx"] = 200                                              # set by something else: a new place
    clock.step(0.6)
    mo.apply(app)
    check(mo.place(app, "sx") == 200 and app.eng.fx["sx"] == 230, f"the place follows a slider set ({app.eng.fx['sx']})")
    clock.step(1.0)
    mo.apply(app)
    check(app.eng.fx["sx"] == 170, "round the new place")
    app.eng.fx["c3"] = 30
    mo.modulators(app).append({"key": "c3", "kind": "lfo", "shape": "square", "period": 2, "depth": 60, "on": True})
    clock.step(1.0)
    mo.apply(app)
    check(app.eng.fx["c3"] == 31, "Custom 3 kept to 31")
    mo.modulators(app)[0]["on"] = False
    mo.apply(app)
    check(app.eng.fx["sx"] == 200 and mo.place(app, "sx") is None, "off: the slider left at its place")
    app.last_hit_at = clock.now()
    mo.modulators(app)[:] = [{"key": "ix", "kind": "beat", "depth": 50, "decay": 0.3, "on": True}]
    clock.step(mo.ATTACK_S)
    mo.apply(app)
    check(app.eng.fx["ix"] == 150 and app.eng.fx["c3"] == 30, f"the beat pushes; c3's modulator gone, it left at 30")
    mo.modulators(app).clear()
    mo.apply(app)
    check(app.eng.fx["ix"] == 100 and app._mod_state == {}, "none left: every slider at its place, nothing kept")
    n = app.eng.pushes
    mo.apply(app)
    check(app.eng.pushes == n, "nothing to do: the engine left alone")
finally:
    clock.release()

print("FAILED:", fails if fails else "none")
sys.exit(1 if fails else 0)
# AI: end
